import React from "react";

function Skills() {
  const skills = [
    "React.js",
    "JavaScript (ES6+)",
    "HTML5 & CSS3",
    "Node.js",
    "Java (OOP & GUI)",
    "MySQL",
    "Git & GitHub",
    "Responsive Web Design",
  ];

  return (
    <section style={styles.container}>
      <h2 style={styles.heading}>My Skills</h2>
      <p style={styles.subtext}>
        Here are some of the technologies and tools I’ve worked with:
      </p>
      <div style={styles.grid}>
        {skills.map((skill, index) => (
          <div key={index} style={styles.card}>
            <span style={styles.text}>{skill}</span>
          </div>
        ))}
      </div>
    </section>
  );
}

const styles = {
  container: {
    padding: "60px 20px",
    maxWidth: "900px",
    margin: "0 auto",
    textAlign: "center",
  },
  heading: {
    fontSize: "2.5rem",
    color: "#0d47a1",
    marginBottom: "10px",
  },
  subtext: {
    fontSize: "1rem",
    color: "#555",
    marginBottom: "40px",
  },
  grid: {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit, minmax(150px, 1fr))",
    gap: "20px",
    justifyItems: "center",
  },
  card: {
    backgroundColor: "#f5f7fa",
    borderRadius: "10px",
    padding: "20px",
    boxShadow: "0 3px 8px rgba(0,0,0,0.1)",
    transition: "all 0.3s ease",
    cursor: "default",
  },
  text: {
    fontWeight: "600",
    color: "#333",
  },
};

export default Skills;
